@js:(function(){
      var UA='Mozilla/5.0 (Windows NT 10.0; Win64; x64) Chrome/134.0.0.0 Safari/537.36';
      var s=String((typeof java!=='undefined' && java.baseUrl) || (typeof baseUrl!=='undefined'?baseUrl:'') || '');
      var m=s.match(/trackId=([^&]+)/);
      if(!m){ var m2=s.match(/\/song\/(\d+)/); if(m2) m=m2; }
      if(!m||!m[1]) return '';
      var tid=m[1];
      try{
        var seo='https://beta-luna.douyin.com/luna/h5/seo_track?track_id='+tid+'&device_platform=web';
        var o1={headers:{'User-Agent':UA,'Referer':'https://www.douyin.com/'}};
        var s1=java.ajax(seo+','+JSON.stringify(o1));
        if(!s1) return '';
        var pu=(JSON.parse(s1).track_player||{}).url_player_info||'';
        if(!pu) return '';
        var o2={headers:{'User-Agent':UA,'Referer':'https://www.douyin.com/'}};
        var s2=java.ajax(pu+','+JSON.stringify(o2));
        if(!s2) return '';
        var pl=((JSON.parse(s2).Result||{}).Data||{}).PlayInfoList||[];
        function val(q){
          q=String(q||'').toLowerCase();
          if(q.indexOf('highest')>=0||q==='hi'||q==='exhigh') return 4;
          if(q.indexOf('higher')>=0||q==='sq'||q==='lossless') return 3;
          if(q.indexOf('normal')>=0||q==='hq') return 2;
          if(q==='lq'||q.indexOf('low')>=0) return 1;
          return 0;
        }
        var best='',bv=-1;
        for(var i=0;i<pl.length;i++){
          var u=pl[i].MainPlayUrl||pl[i].BackupPlayUrl1||pl[i].BackupPlayUrl2||'';
          if(!u) continue;
          var v=val(pl[i].Quality||pl[i].QualityDesc||'');
          if(v>bv){bv=v;best=u;}
        }
        if(!best&&pl.length) best=pl[0].MainPlayUrl||pl[0].BackupPlayUrl1||'';
        return best||'';
      }catch(e){ return ''; }
    })()

