@js:(function(){
  var raw = (typeof result === 'string') ? result : (result ? JSON.stringify(result) : '');
  var list = parseSongs(raw);
  if (list && list.length) return list;
  return [diag(raw)];

  function parseSongs(s){
    try {
      var j = JSON.parse(s);
      var items = j.items || (j.data && j.data.items) || [];
      if (!items || !items.length) return null;
      var out = [];
      for (var i=0;i<items.length;i++){
        var ent = items[i].entity || items[i];
        var tr = (ent.track_wrapper && ent.track_wrapper.track) || ent.track || ent.audio || null;
        if (!tr || !tr.id) continue;
        var al = tr.album || {};
        var arts = tr.artists || [];
        var an=[]; for(var a=0;a<arts.length;a++) an.push(arts[a].name||'');
        var uc = al.url_cover || al.cover || {};
        var ul = uc.urls || uc.url_list || [];
        var cov = (ul && ul.length) ? (ul[0]+(uc.uri||'')) : '';
        out.push({
          name: tr.name||'',
          author: an.join('/'),
          coverUrl: cov,
          detail: 'https://www.qishui.com/song/'+tr.id+'?trackId='+tr.id,
          lastChapter: '时长'+Math.round((tr.duration||0)/1000)+'秒'
        });
      }
      return out.length ? out : null;
    } catch(e){ return null; }
  }

  // 解析不出歌 -> 输出诊断卡：书名=结论，作者=原始返回摘要
  function diag(s){
    var brief='', detail='（空响应）';
    if (!s){ brief='❌ 无返回：请求失败/被拦截'; }
    else {
      detail = s.substring(0,300);
      try {
        var j=JSON.parse(s);
        var code = (j.status_code!==undefined?j.status_code:(j.code!==undefined?j.code:''));
        var msg = j.message || j.msg || j.errmsg || '';
        var no = j.err_no!==undefined?j.err_no:'';
        if (String(s).indexOf('Request denied')>=0 || String(code)==='403'){
          brief='❌ 被拦截(403/网关拒绝)';
        } else if (j.items && !j.items.length){
          brief='⚠️ 接口通但 items 为空（region/风控？）';
        } else if (msg){
          brief='⚠️ 接口返回错误: '+msg+(code?(' (code='+code+')'):'')+(no?(' err_no='+no):'');
        } else if (code!=='' && String(code)!=='0'){
          brief='⚠️ code='+code+(msg?(' '+msg):'');
        } else {
          brief='⚠️ 未知结构，看作者栏原始返回';
        }
      } catch(e){
        if (String(s).indexOf('<html')>=0) brief='❌ 返回HTML页面（非JSON，可能需登录）';
        else brief='⚠️ 非JSON返回';
      }
    }
    return { name: brief, author: detail, coverUrl:'', detail:'', lastChapter:'' };
  }
})()

