  try {
    var j = (typeof result === 'string') ? JSON.parse(result) : result;
    if (!j) return [];
    var out=[], groups = j.result_groups || [];
    for (var g=0; g<groups.length; g++){
      var ds = (groups[g] && groups[g].data) || [];
      for (var i=0;i<ds.length;i++){ var tr=pick(ds[i]); if(tr) out.push(mk(tr)); }
    }
    if (!out.length){
      var arr = j.items || j.data || j.tracks || [];
      for (var k=0;k<arr.length;k++){ var tr2=pick(arr[k]); if(tr2) out.push(mk(tr2)); }
    }
    return out;
  } catch(e){ return []; }
  function pick(n){
    if(!n) return null;
    var e=n.entity||n;
    var t=e.track||e.audio||(e.track_wrapper&&e.track_wrapper.track)||e;
    return (t&&t.id)?t:null;
  }
  function mk(tr){
    var al=tr.album||{}, ar=tr.artists||[], an=[];
    for(var a=0;a<ar.length;a++) an.push(ar[a].name||'');
    var uc=al.url_cover||al.cover||{}, ul=uc.urls||uc.url_list||[];
    var cov=(ul&&ul.length)?(ul[0]+(uc.uri||'')):'';
    return {name:tr.name||'', author:an.join('/'), coverUrl:cov,
            detail:'https://www.qishui.com/song/'+tr.id+'?trackId='+tr.id,
            lastChapter:'时长'+Math.round((tr.duration||0)/1000)+'秒'};
  }
})()

